//! 🔺️ reorder-accessors leaf-owned typed sparse operation diff.
use serde::{Deserialize, Serialize};
use crate::artifacts::gltf::GltfSnapshot;
use crate::artifacts::gltf::schema::snapshot::GltfAccessor;
use crate::artifacts::gltf::schema::diff::GltfDiff;
use crate::artifacts::gltf::schema::mutations::reorder_accessors::mutation::{apply, validate, GltfReorderAccessorsPayload};
use crate::artifacts::gltf::schema::mutations::top_level_collections_private::{accessors_op, family_diff, reject, repair, Change, GltfTopLevelFamily, GltfTopLevelMutationRejection};
pub const ID: &str = "s.stdio.gltf.mutation.reorder-accessors.v1";
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(tag = "kind", rename_all = "camelCase")]
pub enum GltfReorderAccessorsOperation { Insert { position: usize, item: GltfAccessor }, Delete { index: usize, removed: GltfAccessor }, Move { index: usize, position: usize }, Reorder { order: Vec<usize> } }
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "camelCase")]
pub struct GltfReorderAccessorsDiff { pub id: String, pub version: u32, pub touched_paths: Vec<String>, pub payload: GltfReorderAccessorsPayload, pub operation: GltfReorderAccessorsOperation }
fn operation(payload: &GltfReorderAccessorsPayload, base: &GltfSnapshot) -> GltfReorderAccessorsOperation { GltfReorderAccessorsOperation::Reorder { order: payload.order.clone() } }
fn touched_paths(payload: &GltfReorderAccessorsPayload) -> Vec<String> { payload.order.iter().map(|index| format!("document/accessors/{}", index)).chain(std::iter::empty()).collect() }
pub fn validate_diff(diff: &GltfReorderAccessorsDiff, base: &GltfSnapshot) -> Result<(), GltfTopLevelMutationRejection> { if diff.id != ID || diff.version != 1 { return Err(reject("gltf.mutation.invalid-diff-envelope", "diff", "descriptor identity does not match")); } if diff.touched_paths != touched_paths(&diff.payload) { return Err(reject("gltf.mutation.invalid-touched-paths", "diff/touchedPaths", "paths must be concrete payload-derived locations")); } validate(&diff.payload, base)?; if diff.operation != operation(&diff.payload, base) { return Err(reject("gltf.mutation.invalid-sparse-operation", "diff/operation", "operation must equal the direct typed delta")); } Ok(()) }
pub fn apply_diff(diff: &GltfReorderAccessorsDiff, base: &GltfSnapshot) -> Result<GltfSnapshot, GltfTopLevelMutationRejection> { validate_diff(diff, base)?; let mut next = base.clone(); let operation = &diff.operation; match operation { GltfReorderAccessorsOperation::Insert { position, item } => { repair(&mut next.document, GltfTopLevelFamily::Accessors, &Change::Insert(*position))?; next.document.accessors.insert(*position, item.clone());  }, GltfReorderAccessorsOperation::Delete { index, .. } => { accessors_op(&mut next, GltfTopLevelFamily::Accessors, *index, None, None)?;  }, GltfReorderAccessorsOperation::Move { index, position } => { accessors_op(&mut next, GltfTopLevelFamily::Accessors, *index, Some(*position), None)?;  }, GltfReorderAccessorsOperation::Reorder { order } => { accessors_op(&mut next, GltfTopLevelFamily::Accessors, order[0], None, Some(order))?;  } } Ok(next) }
pub fn encode(diff: &GltfReorderAccessorsDiff) -> Result<Vec<u8>, GltfTopLevelMutationRejection> { serde_json::to_vec(diff).map_err(|error| reject("gltf.mutation.encode-failed", "diff", error.to_string())) }
pub fn derive(payload: &GltfReorderAccessorsPayload, base: &GltfSnapshot) -> Result<GltfReorderAccessorsDiff, GltfTopLevelMutationRejection> { validate(payload, base)?; Ok(GltfReorderAccessorsDiff { id: ID.into(), version: 1, touched_paths: touched_paths(payload), payload: payload.clone(), operation: operation(payload, base) }) }
pub fn derive_transitional_gltf_diff(payload: &GltfReorderAccessorsPayload, base: &GltfSnapshot) -> Result<GltfDiff, GltfTopLevelMutationRejection> { let next = apply(payload, base)?; Ok(family_diff(GltfTopLevelFamily::Accessors, base, &next)) }
